  1	package com.pousadamarealta.service;
  2	
  3	import com.pousadamarealta.model.*;
  4	
  5	import java.math.BigDecimal;
  6	import java.time.LocalDate;
  7	import java.time.YearMonth;
  8	import java.time.format.DateTimeFormatter;
  9	import java.util.*;
 10	import java.util.stream.Collectors;
 11	
 12	public class ReportService {
 13	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 14	    private static final BigDecimal TOURISM_TAX_PER_GUEST_PER_NIGHT = new BigDecimal("4.50");
 15	
 16	    private final ReservationService reservationService;
 17	    private final RoomService roomService;
 18	
 19	    public ReportService(ReservationService reservationService, RoomService roomService) {
 20	        this.reservationService = reservationService;
 21	        this.roomService = roomService;
 22	    }
 23	
 24	    public String generateOccupancyReport(LocalDate date) {
 25	        StringBuilder csv = new StringBuilder();
 26	
 27	        csv.append("Pousada Maré Alta,occupancy,").append(date.format(DATE_FORMAT)).append("\n");
 28	        csv.append("room,type,reservation,check_in,check_out\n");
 29	
 30	        List<Reservation> occupiedReservations = reservationService.getAllReservations().stream()
 31	                .filter(r -> r.getStatus() != ReservationStatus.PENDING)
 32	                .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
 33	                .filter(r -> isOccupiedOnDate(r, date))
 34	                .sorted(Comparator.comparing(Reservation::getRoomNumber))
 35	                .toList();
 36	
 37	        for (Reservation reservation : occupiedReservations) {
 38	            Room room = roomService.findByNumber(reservation.getRoomNumber()).orElseThrow();
 39	            csv.append(String.format("%s,%s,%d,%s,%s\n",
 40	                    reservation.getRoomNumber(),
 41	                    room.getType(),
 42	                    reservation.getId(),
 43	                    reservation.getCheckIn().format(DATE_FORMAT),
 44	                    reservation.getCheckOut().format(DATE_FORMAT)));
 45	        }
 46	
 47	        int totalRooms = roomService.getAllRooms().size();
 48	        csv.append(String.format("total,%d/%d\n", occupiedReservations.size(), totalRooms));
 49	
 50	        return csv.toString();
 51	    }
 52	
 53	    public String generateRevenueReport(YearMonth month) {
 54	        StringBuilder csv = new StringBuilder();
 55	
 56	        csv.append("Pousada Maré Alta,revenue,").append(month.format(DateTimeFormatter.ofPattern("yyyy-MM"))).append("\n");
 57	        csv.append("reservation,room,check_in,check_out,status,amount\n");
 58	
 59	        List<Reservation> monthReservations = reservationService.getAllReservations().stream()
 60	                .filter(r -> startsInMonth(r, month))
 61	                .filter(r -> hasRevenue(r))
 62	                .sorted(Comparator.comparing(Reservation::getCheckIn)
 63	                        .thenComparing(Reservation::getId))
 64	                .toList();
 65	
 66	        BigDecimal total = BigDecimal.ZERO;
 67	
 68	        for (Reservation reservation : monthReservations) {
 69	            BigDecimal revenue = calculateRevenue(reservation);
 70	            total = total.add(revenue);
 71	
 72	            csv.append(String.format("%d,%s,%s,%s,%s,%s\n",
 73	                    reservation.getId(),
 74	                    reservation.getRoomNumber(),
 75	                    reservation.getCheckIn().format(DATE_FORMAT),
 76	                    reservation.getCheckOut().format(DATE_FORMAT),
 77	                    reservation.getStatus(),
 78	                    formatDecimal(revenue)));
 79	        }
 80	
 81	        csv.append(String.format("total,%s\n", formatDecimal(total)));
 82	
 83	        return csv.toString();
 84	    }
 85	
 86	    public String generateTourismTaxReport(YearMonth month) {
 87	        StringBuilder csv = new StringBuilder();
 88	
 89	        csv.append("Pousada Maré Alta,tourism-tax,").append(month.format(DateTimeFormatter.ofPattern("yyyy-MM"))).append("\n");
 90	        csv.append("reservation,room,check_in,check_out,guests,nights,tax\n");
 91	
 92	        List<Reservation> paidReservations = reservationService.getAllReservations().stream()
 93	                .filter(r -> startsInMonth(r, month))
 94	                .filter(r -> isPaid(r))
 95	                .sorted(Comparator.comparing(Reservation::getCheckIn)
 96	                        .thenComparing(Reservation::getId))
 97	                .toList();
 98	
 99	        BigDecimal totalTax = BigDecimal.ZERO;
100	
101	        for (Reservation reservation : paidReservations) {
102	            BigDecimal tax = calculateTourismTax(reservation);
103	            totalTax = totalTax.add(tax);
104	
105	            csv.append(String.format("%d,%s,%s,%s,%d,%d,%s\n",
106	                    reservation.getId(),
107	                    reservation.getRoomNumber(),
108	                    reservation.getCheckIn().format(DATE_FORMAT),
109	                    reservation.getCheckOut().format(DATE_FORMAT),
110	                    reservation.getGuests(),
111	                    reservation.getNights(),
112	                    formatDecimal(tax)));
113	        }
114	
115	        csv.append(String.format("total,%s\n", formatDecimal(totalTax)));
116	
117	        return csv.toString();
118	    }
119	
120	    public String generateRatePlansReport(YearMonth month) {
121	        StringBuilder csv = new StringBuilder();
122	
123	        csv.append("Pousada Maré Alta,rate-plans,").append(month.format(DateTimeFormatter.ofPattern("yyyy-MM"))).append("\n");
124	        csv.append("rate_plan,reservations,amount\n");
125	
126	        Map<RatePlan, List<Reservation>> groupedByPlan = reservationService.getAllReservations().stream()
127	                .filter(r -> startsInMonth(r, month))
128	                .filter(r -> hasRevenue(r))
129	                .collect(Collectors.groupingBy(Reservation::getRatePlan));
130	
131	        Map<RatePlan, BigDecimal> revenueByPlan = new EnumMap<>(RatePlan.class);
132	        Map<RatePlan, Integer> countByPlan = new EnumMap<>(RatePlan.class);
133	
134	        for (RatePlan plan : RatePlan.values()) {
135	            List<Reservation> planReservations = groupedByPlan.getOrDefault(plan, Collections.emptyList());
136	            BigDecimal planRevenue = planReservations.stream()
137	                    .map(this::calculateRevenue)
138	                    .reduce(BigDecimal.ZERO, BigDecimal::add);
139	
140	            revenueByPlan.put(plan, planRevenue);
141	            countByPlan.put(plan, planReservations.size());
142	        }
143	
144	        int totalCount = 0;
145	        BigDecimal totalAmount = BigDecimal.ZERO;
146	
147	        for (RatePlan plan : RatePlan.values()) {
148	            int count = countByPlan.get(plan);
149	            BigDecimal amount = revenueByPlan.get(plan);
150	
151	            csv.append(String.format("%s,%d,%s\n",
152	                    plan,
153	                    count,
154	                    formatDecimal(amount)));
155	
156	            totalCount += count;
157	            totalAmount = totalAmount.add(amount);
158	        }
159	
160	        csv.append(String.format("total,%d,%s\n", totalCount, formatDecimal(totalAmount)));
161	
162	        return csv.toString();
163	    }
164	
165	    private boolean isOccupiedOnDate(Reservation reservation, LocalDate date) {
166	        return !date.isBefore(reservation.getCheckIn()) && date.isBefore(reservation.getCheckOut());
167	    }
168	
169	    private boolean startsInMonth(Reservation reservation, YearMonth month) {
170	        YearMonth checkInMonth = YearMonth.from(reservation.getCheckIn());
171	        return checkInMonth.equals(month);
172	    }
173	
174	    private boolean isPaid(Reservation reservation) {
175	        return reservation.getStatus() == ReservationStatus.CONFIRMED ||
176	                reservation.getStatus() == ReservationStatus.CHECKED_IN ||
177	                reservation.getStatus() == ReservationStatus.CHECKED_OUT;
178	    }
179	
180	    private boolean hasRevenue(Reservation reservation) {
181	        BigDecimal revenue = calculateRevenue(reservation);
182	        return revenue.compareTo(BigDecimal.ZERO) > 0;
183	    }
184	
185	    private BigDecimal calculateRevenue(Reservation reservation) {
186	        BigDecimal paid = reservation.getAmountPaid();
187	        BigDecimal refunded = reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO;
188	        return paid.subtract(refunded);
189	    }
190	
191	    private BigDecimal calculateTourismTax(Reservation reservation) {
192	        int guestNights = reservation.getGuests() * reservation.getNights();
193	        return TOURISM_TAX_PER_GUEST_PER_NIGHT.multiply(new BigDecimal(guestNights));
194	    }
195	
196	    private String formatDecimal(BigDecimal value) {
197	        return value.setScale(2).toPlainString();
198	    }
199	}
