 30	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 31	
 32	        Javalin app = Javalin.create(config -> {
 33	            config.jsonMapper(new JavalinJackson(objectMapper, false));
 34	        });
 35	
 36	        app.get("/rooms", roomController::getRooms);
 37	
 38	        app.post("/reservations", reservationController::createReservation);
 39	        app.get("/reservations/{id}", reservationController::getReservation);
 40	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 41	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 42	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 43	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 44	        app.get("/reservations/{id}/document", reservationController::getDocument);
 45	
 46	        app.get("/messages", messageController::getMessages);
 47	
 48	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 49	        app.get("/reports/revenue", reportController::getRevenueReport);
 50	        app.get("/reports/tourism-tax", reportController::getTourismTaxReport);
 51	        app.get("/reports/rate-plans", reportController::getRatePlansReport);
 52	
 53	        app.start(port);
 54	
 55	        System.out.println("Pousada Maré Alta - Sistema de Reservas");
 56	        System.out.println("Server started on port " + port);
 57	    }
 58	
 59	    private static int getPort() {
 60	        String portEnv = System.getenv("PORT");
 61	        if (portEnv != null && !portEnv.isEmpty()) {
 62	            try {
 63	                return Integer.parseInt(portEnv);
 64	            } catch (NumberFormatException e) {
 65	                System.err.println("Invalid PORT environment variable, using default 7070");
 66	            }
 67	        }
 68	        return 7070;
 69	    }
