224	    public String generateRatePlansReport(YearMonth month) {
225	        StringBuilder csv = new StringBuilder();
226	
227	        csv.append("Pousada Maré Alta,rate-plans,").append(month.format(DateTimeFormatter.ofPattern("yyyy-MM"))).append("\n");
228	        csv.append("rate_plan,reservations,amount\n");
229	
230	        Map<RatePlan, List<Reservation>> groupedByPlan = reservationService.getAllReservations().stream()
231	                .filter(r -> startsInMonth(r, month))
232	                .filter(r -> hasRevenue(r))
233	                .collect(Collectors.groupingBy(Reservation::getRatePlan));
234	
235	        Map<RatePlan, BigDecimal> revenueByPlan = new EnumMap<>(RatePlan.class);
236	        Map<RatePlan, Integer> countByPlan = new EnumMap<>(RatePlan.class);
237	
238	        for (RatePlan plan : RatePlan.values()) {
239	            List<Reservation> planReservations = groupedByPlan.getOrDefault(plan, Collections.emptyList());
240	            BigDecimal planRevenue = planReservations.stream()
241	                    .map(this::calculateRevenue)
242	                    .reduce(BigDecimal.ZERO, BigDecimal::add);
243	
244	            revenueByPlan.put(plan, planRevenue);
245	            countByPlan.put(plan, planReservations.size());
246	        }
247	
248	        int totalCount = 0;
249	        BigDecimal totalAmount = BigDecimal.ZERO;
250	
251	        for (RatePlan plan : RatePlan.values()) {
252	            int count = countByPlan.get(plan);
253	            BigDecimal amount = revenueByPlan.get(plan);
254	
255	            csv.append(String.format("%s,%d,%s\n",
256	                    plan,
257	                    count,
258	                    formatDecimal(amount)));
259	
260	            totalCount += count;
261	            totalAmount = totalAmount.add(amount);
262	        }
263	
264	        csv.append(String.format("total,%d,%s\n", totalCount, formatDecimal(totalAmount)));
265	
266	        return csv.toString();
267	    }
