269	    private boolean isOccupiedOnDate(Reservation reservation, LocalDate date) {
270	        return !date.isBefore(reservation.getCheckIn()) && date.isBefore(reservation.getCheckOut());
271	    }
272	
273	    private boolean startsInMonth(Reservation reservation, YearMonth month) {
274	        YearMonth checkInMonth = YearMonth.from(reservation.getCheckIn());
275	        return checkInMonth.equals(month);
276	    }
277	
278	    private boolean isPaid(Reservation reservation) {
279	        return reservation.getStatus() == ReservationStatus.CONFIRMED ||
280	                reservation.getStatus() == ReservationStatus.CHECKED_IN ||
281	                reservation.getStatus() == ReservationStatus.CHECKED_OUT;
282	    }
283	
284	    private boolean hasRevenue(Reservation reservation) {
285	        BigDecimal revenue = calculateRevenue(reservation);
286	        return revenue.compareTo(BigDecimal.ZERO) > 0;
287	    }
288	
289	    private BigDecimal calculateRevenue(Reservation reservation) {
290	        BigDecimal paid = reservation.getAmountPaid();
291	        BigDecimal refunded = reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO;
292	        return paid.subtract(refunded);
293	    }
294	
295	    private BigDecimal calculateTourismTax(Reservation reservation) {
296	        int guestNights = reservation.getGuests() * reservation.getNights();
297	        return TOURISM_TAX_PER_GUEST_PER_NIGHT.multiply(new BigDecimal(guestNights));
298	    }
299	
300	    private String formatDecimal(BigDecimal value) {
301	        return value.setScale(2).toPlainString();
302	    }
303	}
