329	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
330	                                         String guestCpf, LocalDate checkIn, LocalDate checkOut,
331	                                         int guests, RatePlan ratePlan) {
332	        Room room = roomService.findByNumber(roomNumber)
333	                .orElseThrow(() -> new RoomNotFoundException("Room not found"));
334	
335	        if (guests < 1) {
336	            throw new InvalidRequestException("At least one guest is required");
337	        }
338	
339	        if (guests > room.getCapacity()) {
340	            throw new CapacityExceededException("Room capacity exceeded");
341	        }
342	
343	        if (!checkOut.isAfter(checkIn)) {
344	            throw new InvalidRequestException("Check-out must be after check-in");
345	        }
346	
347	        if (isRoomUnavailable(roomNumber, checkIn, checkOut, null)) {
348	            throw new RoomUnavailableException("Room is not available for the selected dates");
349	        }
350	
351	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
352	        BigDecimal subtotal = PricingCalculator.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
353	        BigDecimal discount = PricingCalculator.calculateDiscount(subtotal, ratePlan == RatePlan.NON_REFUNDABLE);
354	        BigDecimal total = PricingCalculator.calculateTotal(subtotal, discount);
355	
356	        Reservation reservation = new Reservation(
357	                nextId.getAndIncrement(),
358	                roomNumber,
359	                guestName,
360	                guestEmail,
361	                guestCpf,
362	                checkIn,
363	                checkOut,
364	                guests,
365	                ratePlan,
366	                nights,
367	                subtotal,
368	                discount,
369	                total
370	        );
371	
372	        reservations.put(reservation.getId(), reservation);
373	        return reservation;
374	    }
