376	    public Reservation confirmReservation(long id) {
377	        Reservation reservation = findById(id)
378	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
379	
380	        if (reservation.getStatus() != ReservationStatus.PENDING) {
381	            throw new OperationNotAllowedException("Only pending reservations can be confirmed");
382	        }
383	
384	        reservation.setStatus(ReservationStatus.CONFIRMED);
385	        reservation.setAmountPaid(reservation.getTotal());
386	
387	        sendConfirmationEmail(reservation);
388	
389	        return reservation;
390	    }
