392	    public Reservation cancelReservation(long id) {
393	        Reservation reservation = findById(id)
394	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
395	
396	        if (reservation.getStatus() == ReservationStatus.CHECKED_IN ||
397	                reservation.getStatus() == ReservationStatus.CHECKED_OUT ||
398	                reservation.getStatus() == ReservationStatus.CANCELLED) {
399	            throw new OperationNotAllowedException("Cannot cancel reservation in current status");
400	        }
401	
402	        BigDecimal refundAmount = BigDecimal.ZERO;
403	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
404	            refundAmount = reservation.getAmountPaid();
405	        }
406	
407	        reservation.setStatus(ReservationStatus.CANCELLED);
408	        reservation.setRefund(refundAmount);
409	
410	        return reservation;
411	    }
