414	        Reservation reservation = findById(id)
415	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
416	
417	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
418	            throw new OperationNotAllowedException("Only confirmed reservations can check in");
419	        }
420	
421	        reservation.setStatus(ReservationStatus.CHECKED_IN);
422	        return reservation;
423	    }
