426	        Reservation reservation = findById(id)
427	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
428	
429	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
430	            throw new OperationNotAllowedException("Only checked-in reservations can check out");
431	        }
432	
433	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
434	        return reservation;
435	    }
