437	    public Document generateDocument(long id) {
438	        Reservation reservation = findById(id)
439	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
440	
441	        if (reservation.getStatus() == ReservationStatus.PENDING ||
442	                reservation.getStatus() == ReservationStatus.CANCELLED) {
443	            throw new OperationNotAllowedException("Document only available for paid reservations");
444	        }
445	
446	        Room room = roomService.findByNumber(reservation.getRoomNumber()).orElseThrow();
447	
448	        return new Document(
449	                "Comprovante de reserva",
450	                reservation.getId(),
451	                reservation.getGuestName(),
452	                reservation.getGuestCpf(),
453	                reservation.getRoomNumber(),
454	                room.getType(),
455	                reservation.getCheckIn(),
456	                reservation.getCheckOut(),
457	                reservation.getNights(),
458	                reservation.getSubtotal(),
459	                reservation.getDiscount(),
460	                reservation.getTotal()
461	        );
462	    }
