472	    private boolean isRoomUnavailable(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeId) {
473	        return reservations.values().stream()
474	                .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
475	                .filter(r -> excludeId == null || r.getId() != excludeId)
476	                .filter(r -> r.getRoomNumber().equals(roomNumber))
477	                .anyMatch(r -> datesOverlap(checkIn, checkOut, r.getCheckIn(), r.getCheckOut()));
478	    }
479	
480	    private boolean datesOverlap(LocalDate start1, LocalDate end1, LocalDate start2, LocalDate end2) {
481	        return start1.isBefore(end2) && start2.isBefore(end1);
482	    }
