505	    private String formatDocument(Document doc) {
506	        StringBuilder sb = new StringBuilder();
507	        sb.append(String.format("%s nº %d\n", doc.getTitle(), doc.getReservationId()));
508	        sb.append(String.format("Hóspede: %s (CPF %s)\n",
