   297	package com.pousadamarealta.util;
   298	
   299	import java.math.BigDecimal;
   300	import java.math.RoundingMode;
   301	import java.time.LocalDate;
   302	import java.time.Month;
   303	
   304	public class PricingCalculator {
   305	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
   306	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
   307	
   308	    public static boolean isHighSeason(LocalDate date) {
   309	        Month month = date.getMonth();
   310	        int day = date.getDayOfMonth();
   311	
   312	        if (month == Month.JULY) {
   313	            return true;
   314	        }
   315	
   316	        if (month == Month.DECEMBER && day >= 15) {
   317	            return true;
   318	        }
   319	
   320	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
   321	            return true;
   322	        }
   323	
   324	        return false;
   325	    }
   326	
   327	    public static BigDecimal roundToCents(BigDecimal value) {
   328	        return value.setScale(2, RoundingMode.HALF_EVEN);
   329	    }
   330	
   331	    public static BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate date) {
   332	        BigDecimal price = baseRate;
   333	        if (isHighSeason(date)) {
   334	            price = price.multiply(HIGH_SEASON_MULTIPLIER);
   335	        }
   336	        return roundToCents(price);
   337	    }
   338	
   339	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
   340	        BigDecimal subtotal = BigDecimal.ZERO;
   341	        LocalDate current = checkIn;
   342	
   343	        while (current.isBefore(checkOut)) {
   344	            BigDecimal nightPrice = calculateNightPrice(baseRate, current);
   345	            subtotal = subtotal.add(nightPrice);
   346	            current = current.plusDays(1);
   347	        }
   348	
   349	        return roundToCents(subtotal);
   350	    }
   351	
   352	    public static BigDecimal calculateDiscount(BigDecimal subtotal, boolean isNonRefundable) {
   353	        if (!isNonRefundable) {
   354	            return BigDecimal.ZERO;
   355	        }
   356	        return roundToCents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
   357	    }
   358	
   359	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
   360	        return roundToCents(subtotal.subtract(discount));
   361	    }
   362	}
